#!/usr/bin/env bash
set -euo pipefail
[[ $# -eq 3 ]]||{ echo "usage: $0 MU SURFACE FEED";exit 2;};mu="$1";surface="$2";feed="$3";case "$mu" in 0.6|0.9);;*)exit 2;;esac;case "$surface" in 12|16|20|24);;*)exit 2;;esac;case "$feed" in 0|2);;*)exit 2;;esac
bench=engineering/shared-flywheel-isolated-bench;root=engineering/chassis-strength-bench/results/shared_flywheel_phase2/gazebo_5d1_p261;tag="${mu/./p}";out="$root/cases/tm_$tag/surface_$surface/feed_$feed";mkdir -p "$out"
telemetry="$(pwd)/$out/telemetry.csv";contacts="$(pwd)/$out/native_contacts.csv";ball_contacts="$(pwd)/$out/ball_contacts.csv";rm -f "$telemetry" "$telemetry.done" "$contacts" "$ball_contacts"
mass_args=(base_mass:=7.404 base_com_x:=0.09386412749865 base_com_z:=0.13227174500270 base_ixx:=0.38652546 base_iyy:=0.35877559 base_izz:=0.54328377 base_ixz:=-0.05214756 drive_wheel_mass:=0.65 drive_wheel_ixx:=0.00154721666667 drive_wheel_iyy:=0.002348125 drive_wheel_izz:=0.00154721666667);tilt=.3490658503988659
xacro "$bench/v3_chassis_flywheel_bench.urdf.xacro" sim_mode:=false validation_fixtures_enabled:=true five_c_enabled:=true five_c_design:=p244 five_c_p244_ramp_enabled:=true five_c_ramp_tip_clearance:=0.008 five_c_cheek_variant:=exposed_shallow five_c_basket_variant:=p251_ski_42 tilt_angle_rad:="$tilt" "${mass_args[@]}" > "$out/model.urdf";gz sdf -p "$out/model.urdf" > "$out/model.sdf"
python3 "$bench/make_5d1_p259_world.py" --model-sdf "$out/model.sdf" --ball-model gazebo/models/tennis_ball_compliant/model.sdf --output "$out/world.sdf" --telemetry "$telemetry" --contacts "$contacts" --ball-contacts "$ball_contacts" --angle-deg 20 --surface-speed "$surface" --tread-mu "$mu" --nip-compression-mm 8 --feed-speed "$feed" --contact-entry-release --max-step-size .00025
export GZ_CONFIG_PATH=/usr/share/gz;physics="$out/physics_plugins";mkdir -p "$physics";ln -sfn /usr/lib/x86_64-linux-gnu/gz-physics-7/engine-plugins/libgz-physics7-dartsim-plugin.so.7 "$physics/libgz-physics7-dartsim-plugin.so";export GZ_SIM_PHYSICS_ENGINE_PATH="$(pwd)/$physics";export GZ_SIM_SYSTEM_PLUGIN_PATH="$(pwd)/$bench/build_p261:$(pwd)/$bench/build_contact_5c:${GZ_SIM_SYSTEM_PLUGIN_PATH:-}";engine=/usr/lib/x86_64-linux-gnu/gz-physics-7/engine-plugins/libgz-physics7-dartsim-plugin.so.7
record="${BENCH_RECORD:-false}";gz_args=(-r -s -v 1 --physics-engine "$engine");if [[ "$record" == true ]];then mkdir -p "$out/replay";gz_args+=(--record-path "$(pwd)/$out/replay" --log-overwrite);fi
timeout --signal=TERM --kill-after=3 180 gz sim "${gz_args[@]}" "$out/world.sdf" > "$out/gazebo.log" 2>&1 &pid=$!;trap 'kill "$pid" 2>/dev/null||true' EXIT;for _ in $(seq 1 1500);do [[ -f "$telemetry.done" ]]&&break;kill -0 "$pid" 2>/dev/null||break;sleep .1;done;[[ -f "$telemetry.done" ]]||{ tail -100 "$out/gazebo.log";exit 1;};kill "$pid" 2>/dev/null||true;wait "$pid" 2>/dev/null||true;trap - EXIT
sha256sum "$bench/criteria_5d1_p261.json" > "$out/criteria.sha256";python3 "$bench/analyze_5d1_p259_run.py" --angle 20 --mu "$mu" --surface "$surface" --repeat 1 --nip-compression-mm 8 --feed-speed "$feed" --telemetry "$telemetry" --contacts "$contacts" --ball-contacts "$ball_contacts" --criteria "$bench/criteria_5d1_p261.json" --output "$out/summary.json"
